import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import { Route, Routes } from 'react-router-dom';
import Home from './pages/Home';
import Services from './pages/Services';
import Contact from './pages/Contact';
import Portfolio from './pages/Portfolio';
import Notice from './pages/Notice';



function App() {
  return (
    <header className="App-header">
      <Navbar collapseOnSelect expand="lg" className="bg-dark"bg="dark" data-bs-theme="dark">
        <Container>
          <Navbar.Brand href="#home">John Deo</Navbar.Brand>
          <Navbar.Toggle aria-controls="responsive-navbar-nav" />
          <Navbar.Collapse id="responsive-navbar-nav">
            <Nav className="ms-auto">
              <Nav.Link href="/">Acceuil</Nav.Link>
              <Nav.Link href="/services">Services</Nav.Link>
              <Nav.Link href="/contact">Contact</Nav.Link>
              <Nav.Link href="/portfolio">Portfolio</Nav.Link>
              <Nav.Link href="/notice">Mentions Légales</Nav.Link>         
            </Nav>
            <Routes>
              <Route path='/' element={<Home/>}></Route>
              <Route path='/' element={<Services/>}></Route>
              <Route path='/' element={<Contact/>}></Route>
              <Route path='/' element={<Portfolio/>}></Route>
              <Route path='/' element={<Notice/>}></Route>
            </Routes>
          </Navbar.Collapse>
        </Container>
      </Navbar>

   </header>
  );
}

export default App;
